head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gLastJob = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        frame.width = 780;
        frame.height = 445;

        // 패널라운드 처리
        $c.cm.PanelToGroupBox(panel_Top);
        scwin.init();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05328.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    // 파일업로드 데이터셋 초기화

    // dts_FileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    dts_FileList.insertRow();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Save_onclick = async function() {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05328.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05328.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        if ((trs_Save.ErrorMsg).indexOf('50014') !== -1) {
            await $c.win.alert('첨부하려는 파일을 열어놓은 경우, 파일 첨부가 불가능 합니다.\r\n첨부하려는 파일을 닫고 다시 진행하시기 바랍니다.');
        } else {
            await $c.win.alert(trs_Save.ErrorMsg);
            // alert_error2(trs_Save);

        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05328.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        if (scwin.gLastJob === "저장") {
            const msg = $c.stf.getMessageParam("MSG-A001", scwin.gLastJob);
            await $c.win.alert(msg);
            // var fr_fn_Search = frame.Provider("../").fn_list_sync;
            // fr_fn_Search();
            // frame.CloseFrame();

        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05328.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name btn_FORM_U1_onclick
 * @description 「Excel 양식」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_FORM_U1_onclick = function() {
    try {
        location.href = "/lstproc/synth_etf_sample.xls";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05328.btn_FORM_U1_onclick" });
    }
};

/**
 * @method
 * @name btn_ReLoad_onclick
 * @description 「Refresh」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ReLoad_onclick = async function() {
    try {
        if (txb_FILE.getValue() === '') {
            await $c.win.alert("[첨부파일]을 선택하세요.");
            file.focus();
            return;
        }
        scwin.gLastJob = "";
        dts_List.removeAll();
        await scwin.loadExcel();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05328.btn_ReLoad_onclick" });
    }
};

/**
 * @method
 * @name file_OnClick
 * @description file 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.file_OnClick = async function() {
    try {
        scwin.gLastJob = "엑셀데이터 불러오기";
        await scwin.selectAttach();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05328.file_OnClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name save
 * @description 저장버튼 클릭 시
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (txb_FILE.getValue() === '') {
        await $c.win.alert("[첨부파일]을 선택하세요.");
        file.focus();
        return;
    }
    if (confirm('저장 하시겠습니까?')) {
        // setObjectValue(txb_acpt_ddtm,"");
        scwin.gLastJob = "저장";
        // SynthEtfTrctptInfo
        trs_Save.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/SynthEtfTrctptInfo.do",
            ref : "dts_FileList",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name loadExcel
 * @description 엑셀파일 데이터 읽기
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.loadExcel = async function() {
    trs_Save.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/SynthEtfTrctptInfo.do",
        ref : "dts_List,dts_FileList",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name alert_error2
 * @description 저장 에러 발생 시
 * @param {*} dtsObj dtsObj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.alert_error2 = async function(dtsObj) {
    const USER_DEFINE = new Array("INTERNAL", "UNDEFINED", "APP_COMPONENT", "BIZ_COMPONENT", "ACTION", "CORE_FRAMEWORK", "WEB_FRAMEWORK", "INFO");
    for (let i = 0; i < USER_DEFINE.length; i++) {
        const errorCount = dtsObj.SrvErrCount(USER_DEFINE[i]);
        let j;
        for (j = 0; j < errorCount; j++) {
            if (dtsObj.SrvErrCode(USER_DEFINE[i], j) === '0') {
                // '0' 임의로 떨군 INFO 메시지
                await $c.win.alert(dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            } else {
                // 기존 에러 메시지
                await $c.win.alert("[CODE: " + dtsObj.SrvErrCode(USER_DEFINE[i], j) + "] " + dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            }
        }
    }
};

/**
 * @method
 * @name selectAttach
 * @description 파일첨부 버튼 클릭 시
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selectAttach = async function() {
    const vFile = file.getValue();
    if (vFile === "" || txb_FILE.getValue() === vFile) {
        return;
    } else if (vFile.substring(vFile.length - 3, vFile.length).toUpperCase() !== "XLS") {
        await $c.win.alert("엑셀파일(*.xls)만 입력하시기 바랍니다.");
        txb_FILE.setValue("");
        return;
    } else {
        dts_List.removeAll();
        txb_FILE.setValue(file.getValue());
        dts_FileList.setCellData(1, "fileInfo", file.getValue());
        dts_FileList.setCellData(1, "fileUrl", file.getValue());
    }
    // 엑셀 파일 불러오기
    await scwin.loadExcel();
};
